+
+	mutex_lock(&flb_obj->lock);
+	if (!domain->preserved_state) {
+		ret = -EINVAL;
+		goto out_unlock;
+	}
+
+	if (iommu->device_ser) {
+		ret = -EBUSY;
+		goto out_unlock;
