index 39c7a34531e8..677c39b0d62f 100644
--- a/fs/tracefs/event_inode.c
+++ b/fs/tracefs/event_inode.c
@@ -124,6 +124,16 @@ static inline void put_ei(struct eventfs_inode *ei)
