+///
+/// ```
+/// # use kernel::sync::atomic::{Atomic, Relaxed};
+/// # use kernel::time::{Delta, delay::fsleep};
+/// use kernel::workqueue::{
+///     new_scoped_work,
+///     Queue,
+///     ScopedQueue,
+///     ScopedWork,
+///     ScopedWorkItem,
+///     ScopedWorkRef,
+/// };
