+impl<T: ScopedWorkItem> Deref for ScopedWork<T> {
+    type Target = ScopedWorkRef<T>;
+
+    #[inline]
+    fn deref(&self) -> &ScopedWorkRef<T> {
+        // SAFETY: The inner `ScopedWorkRef` is always valid and initialized.
+        unsafe { &*self.inner.get() }
+    }
